// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    address owner;

    function setUp() public {
        c = new MultiplicatorX3();
        owner = address(this);
    }

    function testFuzz_property(uint256 value, bool useRevertingCallee) public {
        value = bound(value, 0, 1 ether);

        address callee;
        if (useRevertingCallee) {
            callee = address(new Reverter());
        } else {
            callee = address(new Acceptor());
        }

        vm.deal(owner, value);

        bool ok;
        vm.prank(owner);
        try c.Command{value: value}(callee, "0x") {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

contract Acceptor {
    fallback() external payable {}
    receive() external payable {}
}
